OKs=svg('<path d="M20 6 9 17l-5-5"/>','#1c8f45',12)
def st(t,state='ok'):
    d={'ok':'<span class="d">'+OKs+'</span>','run':'<span class="d"></span>','todo':'<span class="d"></span>'}[state]
    return f'<div class="st {"" if state=="ok" else state}">{d}{t}</div>'
def cond(*c): return '<div class="cond">'+''.join(f'<span class="{"ok" if ok else ""}">{"✓ " if ok else ""}{t}</span>' for t,ok in c)+'</div>'
